<?php

declare(strict_types=1);

require_once __DIR__.'/ProductionLifecycleGuard.php';
require_once __DIR__.'/StorageService.php';
require_once __DIR__.'/ProductionParticipantEligibility.php';

final class ManualParticipantService
{
    private const TYPES=['cast','crew','creative','other'];
    private const STATUSES=['under_review','callback','offered','cast','not_cast','withdrawn'];

    public static function forProduction(PDO $db,int $productionId,bool $includeInactive=false):array
    {
        $s=$db->prepare("SELECT mpc.*,mp.first_name,mp.last_name,COALESCE(NULLIF(mp.display_name,''),CONCAT(mp.first_name,' ',mp.last_name)) person_name,mp.biography,mp.headshot_stored_file_id,mp.private_notes,mp.status profile_status FROM manual_participant_credits mpc JOIN manual_participants mp ON mp.id=mpc.manual_participant_id WHERE mpc.production_id=:production".($includeInactive?'':" AND mpc.active=1 AND mp.status='active'")." ORDER BY mpc.display_order,mp.last_name,mp.first_name");$s->execute(['production'=>$productionId]);return$s->fetchAll();
    }

    public static function availableProfiles(PDO $db,int $productionId):array
    {
        $s=$db->prepare("SELECT mp.id,COALESCE(NULLIF(mp.display_name,''),CONCAT(mp.first_name,' ',mp.last_name)) name FROM manual_participants mp WHERE mp.status='active' AND NOT EXISTS (SELECT 1 FROM manual_participant_credits mpc WHERE mpc.manual_participant_id=mp.id AND mpc.production_id=:production) ORDER BY mp.last_name,mp.first_name");$s->execute(['production'=>$productionId]);return$s->fetchAll();
    }

    public static function addExistingCredit(PDO $db,int $productionId,int $actorId,int $profileId,array $input):int
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$data=self::validate(array_merge(['first_name'=>'Existing','last_name'=>'Profile'],$input));$q=$db->prepare("SELECT id FROM manual_participants WHERE id=:id AND status='active'");$q->execute(['id'=>$profileId]);if(!$q->fetchColumn())throw new RuntimeException('Choose an available manual participant profile.');$q=$db->prepare("INSERT INTO manual_participant_credits (manual_participant_id,production_id,participant_type,roles_json,role_title,casting_status,participation_track,display_order,staff_notes,approve_public_name,approve_public_biography,approve_public_headshot,created_by_user_id,updated_by_user_id) VALUES (:profile,:production,:type,:roles,:role,:status,:track,:sort,:notes,:name_ok,:bio_ok,:headshot_ok,:actor,:actor2)");try{$q->execute(['profile'=>$profileId,'production'=>$productionId,'type'=>$data['type'],'roles'=>$data['roles'],'role'=>$data['role'],'status'=>$data['status'],'track'=>$data['track'],'sort'=>$data['sort'],'notes'=>$data['staff_notes'],'name_ok'=>$data['name_ok'],'bio_ok'=>$data['bio_ok'],'headshot_ok'=>$data['headshot_ok'],'actor'=>$actorId,'actor2'=>$actorId]);}catch(PDOException $e){throw new RuntimeException('That manual participant already has a credit in this production.');}$id=(int)$db->lastInsertId();self::audit($db,$actorId,'manual_participant.credit_added',$id,'Added another production credit to a manual participant.',['production_id'=>$productionId,'manual_participant_id'=>$profileId]);return$id;
    }

    public static function create(PDO $db,string $root,int $productionId,int $actorId,array $input,array $upload):int
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$data=self::validate($input);$stored=null;$db->beginTransaction();try{if((int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$stored=StorageService::store($db,$root,$actorId,$upload);self::assertImage($stored);}$q=$db->prepare("INSERT INTO manual_participants (first_name,last_name,display_name,biography,headshot_stored_file_id,private_notes,created_by_user_id,updated_by_user_id) VALUES (:first,:last,:display,:bio,:headshot,:notes,:actor,:actor2)");$q->execute(['first'=>$data['first'],'last'=>$data['last'],'display'=>$data['display'],'bio'=>$data['bio'],'headshot'=>$stored['stored_file_id']??null,'notes'=>$data['private_notes'],'actor'=>$actorId,'actor2'=>$actorId]);$profileId=(int)$db->lastInsertId();$q=$db->prepare("INSERT INTO manual_participant_credits (manual_participant_id,production_id,participant_type,roles_json,role_title,casting_status,participation_track,display_order,staff_notes,approve_public_name,approve_public_biography,approve_public_headshot,created_by_user_id,updated_by_user_id) VALUES (:profile,:production,:type,:roles,:role,:status,:track,:sort,:notes,:name_ok,:bio_ok,:headshot_ok,:actor,:actor2)");$q->execute(['profile'=>$profileId,'production'=>$productionId,'type'=>$data['type'],'roles'=>$data['roles'],'role'=>$data['role'],'status'=>$data['status'],'track'=>$data['track'],'sort'=>$data['sort'],'notes'=>$data['staff_notes'],'name_ok'=>$data['name_ok'],'bio_ok'=>$data['bio_ok'],'headshot_ok'=>$data['headshot_ok'],'actor'=>$actorId,'actor2'=>$actorId]);$creditId=(int)$db->lastInsertId();self::audit($db,$actorId,'manual_participant.created',$creditId,'Created manual production participant.',['production_id'=>$productionId,'manual_participant_id'=>$profileId]);$db->commit();return$creditId;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($stored&&isset($stored['absolute_path']))@unlink((string)$stored['absolute_path']);throw $e instanceof RuntimeException?$e:new RuntimeException('The manual participant could not be created.');}
    }

    public static function update(PDO $db,string $root,int $productionId,int $actorId,int $creditId,array $input,array $upload):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);$data=self::validate($input);$stored=null;$db->beginTransaction();try{$q=$db->prepare('SELECT mpc.*,mp.headshot_stored_file_id FROM manual_participant_credits mpc JOIN manual_participants mp ON mp.id=mpc.manual_participant_id WHERE mpc.id=:id AND mpc.production_id=:production FOR UPDATE');$q->execute(['id'=>$creditId,'production'=>$productionId]);$row=$q->fetch();if(!$row)throw new RuntimeException('That manual participant is unavailable.');$headshot=$row['headshot_stored_file_id'];if((int)($upload['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$stored=StorageService::store($db,$root,$actorId,$upload);self::assertImage($stored);$headshot=(int)$stored['stored_file_id'];}$db->prepare('UPDATE manual_participants SET first_name=:first,last_name=:last,display_name=:display,biography=:bio,headshot_stored_file_id=:headshot,private_notes=:notes,updated_by_user_id=:actor WHERE id=:id')->execute(['first'=>$data['first'],'last'=>$data['last'],'display'=>$data['display'],'bio'=>$data['bio'],'headshot'=>$headshot?:null,'notes'=>$data['private_notes'],'actor'=>$actorId,'id'=>(int)$row['manual_participant_id']]);$db->prepare('UPDATE manual_participant_credits SET participant_type=:type,roles_json=:roles,role_title=:role,casting_status=:status,participation_track=:track,display_order=:sort,staff_notes=:notes,approve_public_name=:name_ok,approve_public_biography=:bio_ok,approve_public_headshot=:headshot_ok,updated_by_user_id=:actor WHERE id=:id')->execute(['type'=>$data['type'],'roles'=>$data['roles'],'role'=>$data['role'],'status'=>$data['status'],'track'=>$data['track'],'sort'=>$data['sort'],'notes'=>$data['staff_notes'],'name_ok'=>$data['name_ok'],'bio_ok'=>$data['bio_ok'],'headshot_ok'=>$data['headshot_ok'],'actor'=>$actorId,'id'=>$creditId]);self::audit($db,$actorId,'manual_participant.updated',$creditId,'Updated manual production participant.',['production_id'=>$productionId]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($stored&&isset($stored['absolute_path']))@unlink((string)$stored['absolute_path']);throw $e instanceof RuntimeException?$e:new RuntimeException('The manual participant could not be updated.');}
    }

    public static function archive(PDO $db,int $productionId,int $actorId,int $creditId):void{ProductionLifecycleGuard::assertWritable($db,$productionId);$q=$db->prepare('UPDATE manual_participant_credits SET active=0,updated_by_user_id=:actor WHERE id=:id AND production_id=:production AND active=1');$q->execute(['actor'=>$actorId,'id'=>$creditId,'production'=>$productionId]);if(!$q->rowCount())throw new RuntimeException('That manual participant is already inactive or unavailable.');self::audit($db,$actorId,'manual_participant.archived',$creditId,'Archived manual production participant.',['production_id'=>$productionId]);}

    public static function transfer(PDO $db,int $productionId,int $actorId,int $creditId,int $studentId,array $choices):void
    {
        ProductionLifecycleGuard::assertWritable($db,$productionId);if($studentId<1)throw new RuntimeException('Choose a registered participant destination.');$db->beginTransaction();try{$q=$db->prepare("SELECT mpc.*,COALESCE(NULLIF(mp.display_name,''),CONCAT(mp.first_name,' ',mp.last_name)) display_name,mp.biography,mp.headshot_stored_file_id FROM manual_participant_credits mpc JOIN manual_participants mp ON mp.id=mpc.manual_participant_id WHERE mpc.id=:id AND mpc.production_id=:production AND mpc.active=1 FOR UPDATE");$q->execute(['id'=>$creditId,'production'=>$productionId]);$row=$q->fetch();if(!$row)throw new RuntimeException('That manual participant is unavailable.');ProductionParticipantEligibility::assertManager($db,$actorId,$productionId,false);ProductionParticipantEligibility::assertEligible($db,$productionId,$studentId);$db->prepare('INSERT INTO student_profiles (user_id,preferred_name,short_bio,headshot_stored_file_id,updated_by_user_id) VALUES (:user,:name,:bio,:headshot,:actor) ON DUPLICATE KEY UPDATE preferred_name=IF(:copy_name=1,VALUES(preferred_name),preferred_name),short_bio=IF(:copy_bio=1,VALUES(short_bio),short_bio),headshot_stored_file_id=IF(:copy_headshot=1,VALUES(headshot_stored_file_id),headshot_stored_file_id),updated_by_user_id=:actor2')->execute(['user'=>$studentId,'name'=>!empty($choices['name'])?$row['display_name']:null,'bio'=>!empty($choices['biography'])?$row['biography']:null,'headshot'=>!empty($choices['headshot'])?$row['headshot_stored_file_id']:null,'actor'=>$actorId,'copy_name'=>!empty($choices['name'])?1:0,'copy_bio'=>!empty($choices['biography'])?1:0,'copy_headshot'=>!empty($choices['headshot'])?1:0,'actor2'=>$actorId]);if(!empty($choices['credit'])){$q=$db->prepare("INSERT INTO production_casting_records (production_id,user_id,casting_status,role_title,participation_track,staff_notes,created_by_user_id) VALUES (:production,:user,:status,:role,:track,:notes,:actor) ON DUPLICATE KEY UPDATE casting_status=VALUES(casting_status),role_title=VALUES(role_title),participation_track=VALUES(participation_track),staff_notes=CONCAT_WS('\n',staff_notes,VALUES(staff_notes)),updated_at=CURRENT_TIMESTAMP");$q->execute(['production'=>$productionId,'user'=>$studentId,'status'=>$row['casting_status'],'role'=>$row['role_title'],'track'=>$row['participation_track'],'notes'=>$row['staff_notes'],'actor'=>$actorId]);}$db->prepare('UPDATE manual_participant_credits SET active=0,transferred_to_user_id=:user,transferred_at=CURRENT_TIMESTAMP,updated_by_user_id=:actor WHERE id=:id')->execute(['user'=>$studentId,'actor'=>$actorId,'id'=>$creditId]);$db->prepare("UPDATE manual_participants SET status=IF(EXISTS(SELECT 1 FROM manual_participant_credits active_credit WHERE active_credit.manual_participant_id=manual_participants.id AND active_credit.active=1),'active','transferred'),transferred_to_user_id=:user,transferred_at=CURRENT_TIMESTAMP,updated_by_user_id=:actor WHERE id=:id")->execute(['user'=>$studentId,'actor'=>$actorId,'id'=>(int)$row['manual_participant_id']]);self::audit($db,$actorId,'manual_participant.transferred',$creditId,'Transferred approved manual participant data to a registered participant.',['production_id'=>$productionId,'student_user_id'=>$studentId,'choices'=>array_keys(array_filter($choices))]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e instanceof RuntimeException?$e:new RuntimeException('The manual participant transfer could not be completed.');}
    }

    public static function publicCastingRows(PDO $db,int $productionId,string $status):array{$q=$db->prepare("SELECT COALESCE(NULLIF(mp.display_name,''),CONCAT(mp.first_name,' ',mp.last_name)) name,mpc.role_title role,mpc.participation_track,'manual' identity_type FROM manual_participant_credits mpc JOIN manual_participants mp ON mp.id=mpc.manual_participant_id AND mp.status='active' WHERE mpc.production_id=:production AND mpc.active=1 AND mpc.casting_status=:status AND mpc.approve_public_name=1 ORDER BY mpc.display_order,mp.last_name,mp.first_name");$q->execute(['production'=>$productionId,'status'=>$status]);return$q->fetchAll();}

    private static function validate(array $input):array{$first=trim((string)($input['first_name']??''));$last=trim((string)($input['last_name']??''));$display=trim((string)($input['display_name']??''));$bio=trim((string)($input['biography']??''));$role=trim((string)($input['role_title']??''));$roles=array_values(array_filter(array_map('trim',preg_split('/[,\n]+/',(string)($input['roles']??$role))?:[])));$type=(string)($input['participant_type']??'cast');$status=(string)($input['casting_status']??'under_review');if($first===''||$last===''||mb_strlen($first)>100||mb_strlen($last)>100||mb_strlen($display)>190)throw new RuntimeException('Enter valid first and last names.');if(!in_array($type,self::TYPES,true)||!in_array($status,self::STATUSES,true))throw new RuntimeException('Choose valid participant and casting statuses.');if(mb_strlen($bio)>5000||mb_strlen($role)>500||count($roles)>20)throw new RuntimeException('One or more participant fields are too long.');return['first'=>$first,'last'=>$last,'display'=>$display?:null,'bio'=>$bio?:null,'private_notes'=>trim((string)($input['private_notes']??''))?:null,'type'=>$type,'roles'=>json_encode($roles,JSON_THROW_ON_ERROR),'role'=>$role?:implode(', ',$roles),'status'=>$status,'track'=>trim((string)($input['participation_track']??''))?:null,'sort'=>(int)($input['display_order']??0),'staff_notes'=>trim((string)($input['staff_notes']??''))?:null,'name_ok'=>!empty($input['approve_public_name'])?1:0,'bio_ok'=>!empty($input['approve_public_biography'])?1:0,'headshot_ok'=>!empty($input['approve_public_headshot'])?1:0];}
    private static function assertImage(array $stored):void{if(!in_array((string)($stored['mime_type']??''),['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('Headshots must be JPG, PNG, or WebP images.');}
    private static function audit(PDO $db,int $actor,string $event,int $id,string $summary,array $metadata):void{$q=$db->prepare("INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,'manual_participant_credit',:id,:summary,:metadata)");$q->execute(['actor'=>$actor,'event'=>$event,'id'=>$id,'summary'=>$summary,'metadata'=>json_encode($metadata,JSON_THROW_ON_ERROR)]);}
}
